package io.spring.infrastructure.service;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.spring.core.service.JwtService;
import io.spring.core.user.User;
import java.util.Date;
import java.util.Optional;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class DefaultJwtService implements JwtService {

    private final SecretKey signingKey;

    private final SignatureAlgorithm signatureAlgorithm;

    private int sessionTime;

    @Autowired
    public DefaultJwtService(@Value("${jwt.secret}") String secret, @Value("${jwt.sessionTime}") int sessionTime) {
        this.sessionTime = sessionTime;
        signatureAlgorithm = SignatureAlgorithm.HS512;
        this.signingKey = new SecretKeySpec(secret.getBytes(), signatureAlgorithm.getJcaName());
    }

    @Override
    public String toToken(User user) {
        return Jwts.builder().setSubject(user.getId()).setExpiration(expireTimeFromNow()).signWith(signingKey).compact();
    }

    @Override
    public Optional<String> getSubFromToken(String token) {
        try {
            Jws<Claims> claimsJws = Jwts.parserBuilder().setSigningKey(signingKey).build().parseClaimsJws(token);
            return Optional.ofNullable(claimsJws.getBody().getSubject());
        } catch (Exception e) {
            return Optional.empty();
        }
    }

    private Date expireTimeFromNow() {
        return new Date(System.currentTimeMillis() + sessionTime * 1000L);
    }
}

