package io.spring.infrastructure.service;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.spring.core.user.User;
import java.util.Date;
import javax.crypto.spec.SecretKeySpec;
import org.junit.jupiter.api.Test;

public class DefaultJwtServiceTest {

  // GreyTest trace: toToken | STMT-1 | BR-024 -> TP-037 -> TC-1886
  @Test
  public void setsExpirationApproximatelyOneSecondAfterGeneration() {
    String secret = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
    DefaultJwtService service = new DefaultJwtService(secret, 1);
    User user = new User("qa@example.com", "qa-user", "password", "", "");
    long beforeGeneration = System.currentTimeMillis();

    String token = service.toToken(user);

    long afterGeneration = System.currentTimeMillis();
    Jws<Claims> parsed = Jwts.parserBuilder()
        .setSigningKey(new SecretKeySpec(secret.getBytes(), SignatureAlgorithm.HS512.getJcaName()))
        .build()
        .parseClaimsJws(token);
    Date expiration = parsed.getBody().getExpiration();
    assertNotNull(expiration);
    assertTrue(expiration.getTime() >= beforeGeneration + 1000L);
    assertTrue(expiration.getTime() <= afterGeneration + 1000L);
  }
}
